INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Humanoid', 'Humanoid is a parody sci-fi arcade-style run-and-gun shoot ''em up in the style of an early 8-bit arcade game—with the added bonus that you can actually win. To survive, you need to play aggressively: you''re rewarded for acting fast and clearing rooms. It is simple to play, difficult to win.' FROM games WHERE igdb_id = 393495 ON CONFLICT (game_id, language_code) DO NOTHING;
