INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bravery', 'BRAVERY is a third-person 3D adventure game in which players guide a fragile matchstick character through vast, detailed environments that appear enormous in scale. Gameplay focuses on exploration, tense chase sequences, and interactive fire mechanics that allow objects to be ignited. Throughout the journey, players discover hidden areas and capture enigmatic orbs that are sealed within restored magical mirrors, shaping progression through the world.' FROM games WHERE igdb_id = 391078 ON CONFLICT (game_id, language_code) DO NOTHING;
