INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteroid Patrol', 'Bang bang! Shoot raining asteroids, dodge attacks of flying insects and battle against huge weird monsters! Gain exp, level up, pick perk and then rinse & repeat. Story? Nobody cares. If you are looking for a difficult and punishing game, don''t leave without playing this one.' FROM games WHERE igdb_id = 390560 ON CONFLICT (game_id, language_code) DO NOTHING;
