INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hill Defender', 'You’ve claimed the best spot on Earth, but invaders want it. Defend your camp from waves of enemies trying to destroy your base or throw you off the cliff. Use ballistas, catapults, and spells to stop them. Earn rewards, upgrade your defenses, and survive stronger waves. Never let your camp fall!' FROM games WHERE igdb_id = 349933 ON CONFLICT (game_id, language_code) DO NOTHING;
