INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Gozen', 'In Ouma, samurai Sakura Ouka, jobless and foolish, loses her home. She aids Suzune, sparking a quest to revive the Sakura Style. They aim for the Gozenjiai, facing trials in a Japanese-style action RPG. Complete requests, build reputation, and master thrilling battles to win!' FROM games WHERE igdb_id = 391440 ON CONFLICT (game_id, language_code) DO NOTHING;
