INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War in Spain 1936-39', 'With dozens of new features, new art, and engine improvements, War In Spain 1936-39 is the most realistic and engrossing WWII-era European theater game available. The most historical and detailed order of battle for the Spanish Civil War ever put into a wargame!
