INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bring A Knife To A Gun Fight', 'Bring a Knife to a Gun Fight, or BAKTAGF for short, is a high schooler student project that started at the Becker School of Design & Technology''s Next Level Summer Games Studio. It is a 2D sidescroller action platformer in which you play as Bill Hawk (cousin of Tony Hawk), a falsely imprisoned man in a tyrannical regimes prison. Vying for his freedom, he wields a knife with a chain to make his great escape.' FROM games WHERE igdb_id = 387228 ON CONFLICT (game_id, language_code) DO NOTHING;
