INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Condemned to Clean', 'You are a cleaner not by choice, but by necessity. A single-player eco-activist simulator that aims to bring life back to an old beach in a provincial town. Explore abandoned embankments and courtyards, collect rubbish, sort resources, and uncover the history of this forgotten place.' FROM games WHERE igdb_id = 372842 ON CONFLICT (game_id, language_code) DO NOTHING;
