INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bult: Hunting Simulator', 'BULT: Hunting Simulator is a hunting simulation game focused on waterfowl hunting. The game features a realistic shooting model based on ballistic calculations, dynamic bird behavior driven by an AI ecosystem, and tools such as decoys, calls, and a hunting boat. Players explore natural wetland environments influenced by weather, time of day, and seasonal activity' FROM games WHERE igdb_id = 380724 ON CONFLICT (game_id, language_code) DO NOTHING;
