INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza Kiwami 3', 'Continue the story of ex-yakuza Kazuma Kiryu as he fights to protect those he loves in an extreme remake of Yakuza 3 that evolves every aspect of the beloved game. The bustling streets of Okinawa and Tokyo come to life in stunning detail with reimagined combat taking brutal brawling action to the next level. Added scenes deliver more depth and emotion to the beloved story with new and enhanced side experiences that immerse you in the world like never before, and more.' FROM games WHERE igdb_id = 368182 ON CONFLICT (game_id, language_code) DO NOTHING;
