INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wildchain: Rewild The World', 'Wildchain is a cozy animal puzzle game that invites players to restore habitats and care for rescued wildlife through challenging match-3 gameplay. Adopt animals, discover their stories, and grow a calming sanctuary designed to feel playful and pressure-free. Beyond the screen, Wildchain connects your progress to real-world conservation efforts.' FROM games WHERE igdb_id = 391651 ON CONFLICT (game_id, language_code) DO NOTHING;
