INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatherhood Legacy', 'Fatherhood Legacy is an immersive narrative that follows Bryson, a young gamer, as he clashes with his father, Booker, over his future. Through an emotional journey across the city and a meditation-induced flashback to Booker’s past, the two learn to communicate, discover their similarities, and begin overcoming their family’s wounds. Blending interactive storytelling with Black history, gaming culture, and emerging technology, this project explores healing, resilience, and the power of understanding across generations.' FROM games WHERE igdb_id = 354273 ON CONFLICT (game_id, language_code) DO NOTHING;
