INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pipeline Tycoon', 'Become the master of flow in Pipeline Tycoon, a strategic puzzle experience built around planning, logic, and efficiency. Your goal is simple: connect the correct pipelines to complete each system — but the challenges grow as you progress. Navigate obstacles, optimize limited space, and think ahead to solve hundreds of handcrafted levels. With intuitive controls, clean visuals, and progressively advanced puzzles, Pipeline Tycoon offers a relaxing yet deeply satisfying journey for fans of clever, skill-based puzzle games.' FROM games WHERE igdb_id = 388304 ON CONFLICT (game_id, language_code) DO NOTHING;
