INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Hori', 'Join Hori and his lovable crew of baby astronauts and their loyal Bernese Mountain Dog, Charlie, as they blast off on a thrilling journey across the galaxy! In The Adventures of Hori, you''ll unravel cosmic mysteries, outsmart villainous cats known as the “Ronronneurs Maléfiques,” and discover magical objects like the Destructive Lollipop, all while forging bonds of friendship and teamwork. This heartwarming and humorous space tale is brought to life with adorable cartoon visuals, interactive choices, and immersive storytelling perfect for young players and families alike.' FROM games WHERE igdb_id = 392285 ON CONFLICT (game_id, language_code) DO NOTHING;
