INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Standoff', 'Test your reflexes in Samurai Standoff, victory and defeat are decided in the blink of an eye. Take on the role of a lawless mercenary or samurai, in a quick-draw dueling game set in fictional Japan. Prove your focus and speed in multiplayer, or immerse yourself in a choices-driven story mode.' FROM games WHERE igdb_id = 385921 ON CONFLICT (game_id, language_code) DO NOTHING;
