INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hunter-simulator-vr-wild-hunting', 391345, '2026-01-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqhh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc126mc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter Simulator VR: Wild Hunting', 'Hunter Simulator VR: Wild Hunting invites you into the serene yet thrilling world of the wilderness. Step into dense forests, misty mountains, and expansive landscapes where every rustle in the trees could signal your next prey. Feel the tension build as you stalk elusive animals, plan your approach, and experience the unmatched satisfaction of a perfect hunt. With full VR immersion, every movement, every shot, and every decision is in your hands, making each expedition a unique adventure.' FROM games WHERE igdb_id = 391345 ON CONFLICT (game_id, language_code) DO NOTHING;
