INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twin Rockets', 'Twin Rockets is a game in which you control a rocket in space. You need to control her left and right rocket boosters. When you press left, you activate the left accelerator, thereby turning the rocket to the right, and vice versa. You receive points when collecting bonus objects along your way. You will lose if you fly off the playing field or if you crash into dangerous objects along the way.' FROM games WHERE igdb_id = 392290 ON CONFLICT (game_id, language_code) DO NOTHING;
