INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Happy Ball Rush', 'Happy Ball Rush is a vibrant side-scrolling blaster game where precision, timing, and quick reflexes are your keys to victory. Take control of your rolling ball blaster, shoot through waves of numbered balloons, collect shining coins, and push your skills to the limit in an ever-moving world full of surprises.' FROM games WHERE igdb_id = 391328 ON CONFLICT (game_id, language_code) DO NOTHING;
