INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don`t Peek', 'Don’t Peek is a cooperative psychological horror in a cyberpunk style, blending elements of survival and escape. Experience the atmosphere of fear and uncertainty, make critical choices, and control the fate of your friends — will you save them or leave them to perish in this nightmare?' FROM games WHERE igdb_id = 374450 ON CONFLICT (game_id, language_code) DO NOTHING;
