INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadows of the Werewolf', 'Shadows of the Werewolf is a cinematic, third-person action-adventure game that places players in a suspenseful, horror-filled world. The story unfolds across various locations, including a suburban home and a mysterious forest retreat, where an innocent couple faces a relentless werewolf and other monstrous creatures. Players will engage in tense exploration, object interaction, and combat, using stealth and strategy to hide, fight, and escape from supernatural threats. The game blends elements of classic horror films and survival horror games, offering a narrative-driven, single-player experience filled with fear, suspense, and the challenge of survival under the full moon.' FROM games WHERE igdb_id = 315060 ON CONFLICT (game_id, language_code) DO NOTHING;
