INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exit: Echoes of Insanity', 'Exit: Echoes of Insanity es un juego indie de survival horror en el que estás atrapado en un misterioso edificio lleno de secretos. Explora oscuras estancias, resuelve puzles y esquiva una presencia desconocida que siempre te acecha. Con una atmósfera opresiva y una narrativa intrigante, el juego combina exploración, tensión y supervivencia en una experiencia intensa.' FROM games WHERE igdb_id = 395145 ON CONFLICT (game_id, language_code) DO NOTHING;
