INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abashed', 'Abashed is a 2.5D narrative-driven side-scrolling game that lets you explore the life of Issac, a man living with psychosis. One day waking up all alone, he sets out to find the truth behind his missing partner. On the way he finds himself needing to confront his deepest fears and the darkest secrets. Join Issac in this story of love, loss, fear, and acceptance. Reality is not what it seems.' FROM games WHERE igdb_id = 329610 ON CONFLICT (game_id, language_code) DO NOTHING;
