INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nature Minds', 'Nature Minds is an action-adventure RPG where you play as Tareq, a young warrior chosen by the ancient Bracelet of Dilmun. As nature falters and forgotten realms awaken, Tareq discovers that the force behind the world’s disturbance is Gilgamesh—the immortal king who gained endless life through the Plant of Immortality and now seeks to reshape creation according to his vision.
