INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elton Manor: Requiem of the Cursed Roses', 'At the beginning of the 20th century, a “maid”, Anna, worked diligently every day in a quiet manor. However, in an accident, the gaps in his memory swept over him. Abnormal colleagues, confused gender, vague dreams...While Anna was at a loss, a group of strangers visited the manor, and a long-hidden mystery quietly unfolded.' FROM games WHERE igdb_id = 392030 ON CONFLICT (game_id, language_code) DO NOTHING;
