INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pass the Fear', 'Pass the Fear is a roguelite bullet-hell shooter. A catastrophic Witch’s Disaster strikes without warning, and chaotic magic forms the ancient Wall of Storms. Its corruption spreads relentlessly across the island. As a demon hunter trapped within, you must find a way to escape before dawn breaks.' FROM games WHERE igdb_id = 381896 ON CONFLICT (game_id, language_code) DO NOTHING;
