INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinite Scribe', 'Infinite Scribe is a narrative-driven role-playing game developed by Bunnyhug Studios that utilizes generative technology to facilitate dynamic, player-led storytelling. Unlike traditional interactive fiction with fixed branching paths, the title employs a real-time storytelling engine that reacts to player input to generate evolving plots, high-quality audio narration, and custom-styled chapter illustrations.
