INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-jumping-cat--1', 392287, '2026-01-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqgg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc12bh7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Jumping Cat', 'Dive into high-speed arcade action inside a glowing, ever-shifting tunnel. Collect energy cubes, dodge incoming obstacles, and push your reflexes to the limit as the pace intensifies. Simple to learn but endlessly addictive, every run challenges you to survive longer, score higher, and master the perfect flow.' FROM games WHERE igdb_id = 392287 ON CONFLICT (game_id, language_code) DO NOTHING;
