INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinigami Hime to Ishokan no Kaibutsu', 'This game tells a story of heart-to-heart connections and salvation surrounding Mono, a girl who visits the medical facility “Ishokan” in hopes of saving her older sister, who has been afflicted by the terrifying “Shinigami Disease”; Melhendia, a goat-like creature who seeks to exploit her; and the girls who the disease have transformed into strange creatures.' FROM games WHERE igdb_id = 335578 ON CONFLICT (game_id, language_code) DO NOTHING;
