INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life is Strange: Reunion', 'Life is Strange: Reunion is the thrilling finale to the Max and Chloe saga, a chapter that brings their book to a close. This is a full circle moment for both developers and fans—one that builds on everything that has come before. And even as the game delivers a reunion long-thought impossible, it also caps off our time at Caledon University in a literal blaze of glory.' FROM games WHERE igdb_id = 386431 ON CONFLICT (game_id, language_code) DO NOTHING;
