INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lonely Hospital', 'In an abandoned hospital long forgotten by time, the hallways are littered with shattered glass. Dim, flickering lights cast distorted shadows across peeling walls, while pieces of the ceiling occasionally break loose and crash to the floor, echoing through the empty corridors. Everything around Sophie feels strangely unreal — as if the hospital exists somewhere between memory and nightmare, more atmospheric than truly physical.' FROM games WHERE igdb_id = 390972 ON CONFLICT (game_id, language_code) DO NOTHING;
