INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eldritch Escape', 'In this roguelike bullet-heaven, Earth has been consumed by an ancient eldritch god. Form a customizable squad of survivors and explore decaying, metroidvania-inspired worlds trapped within the god’s belly. Battle endless waves of nightmarish creatures, extract resources, rescue survivors, uncover forbidden knowledge, and search for a way out.
