INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baston', 'In Baston, a branch of the Colombian Cartel quietly embeds itself in the outskirts of Milenagrad in eastern Russia, striking a deal with corrupt local police to peddle illicit goods and harass the townsfolk. Major Stepanovich, one of the few honest officers left, reaches out to an old friend—Gena "Baston"—who has just returned and is ready to set things right.' FROM games WHERE igdb_id = 388344 ON CONFLICT (game_id, language_code) DO NOTHING;
