INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate''s Masquerade: Otome Visual Novel', 'Uncover the mystery of your fallen noble lineage and navigate an imperial court brimming with secrets and lies. In this manhwa-inspired dark fantasy romance, love is a weapon and trust is fatal. Beautiful animation. Brutal consequences. Will you hunt the monsters, or will you become one yourself?' FROM games WHERE igdb_id = 334310 ON CONFLICT (game_id, language_code) DO NOTHING;
