INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where Time Ends', 'Where Time Ends is a psychological puzzle game that follows a grieving protagonist determined to build a time machine to see his deceased mother one last time. As players construct the machine piece by piece, they must solve challenging puzzles while reality slowly begins to fracture. With nine unique endings that explore different interpretations of grief, obsession, and acceptance, the game offers an emotional and introspective experience that blends mystery, logic, and psychological tension.' FROM games WHERE igdb_id = 363568 ON CONFLICT (game_id, language_code) DO NOTHING;
