INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape: Backrooms Horror VR', 'Escape – Backrooms Horror VR plunges you into a surreal and claustrophobic world where reality feels warped and danger lurks around every corner. You awaken in dimly lit, maze-like corridors with no memory of how you got there, and your only goal is to find a way out. Every room holds secrets, puzzles, and hidden clues, but the darkness is not empty—traps and creatures roam, ready to turn your exploration into a nightmare. The oppressive atmosphere keeps your heart racing and your senses alert as you inch closer to freedom.' FROM games WHERE igdb_id = 391175 ON CONFLICT (game_id, language_code) DO NOTHING;
